changeSet.sql:
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE app_user (
    id uuid PRIMARY KEY,
    display_name varchar(100) NOT NULL
);

CREATE TABLE club (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(200) NOT NULL UNIQUE,
    display_name varchar(200)
);

CREATE TABLE player (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(200) NOT NULL UNIQUE,
    display_name varchar(200),
    tournament_alias varchar(200),
    search_vector tsvector GENERATED ALWAYS AS (
        to_tsvector('simple'::regconfig,
            coalesce(name, '') || ' ' || coalesce(display_name, '')
        )
    ) STORED
);
CREATE INDEX player_search_vector_idx ON player USING gin (search_vector);

CREATE TABLE match (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    rel_path varchar(1000) NOT NULL UNIQUE,
    year smallint,
    month smallint,
    match_date date,
    club_id uuid REFERENCES club(id),
    tournament boolean NOT NULL DEFAULT false,
    duration_seconds integer,
    size_mbytes integer NOT NULL,
    validation_error text,
    indexed_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX match_year_month_idx ON match (year, month);
CREATE INDEX match_club_idx ON match (club_id);
CREATE INDEX match_date_idx ON match (match_date);

CREATE TABLE match_player (
    match_id uuid NOT NULL REFERENCES match(id) ON DELETE CASCADE,
    player_id uuid NOT NULL REFERENCES player(id),
    position smallint NOT NULL,
    PRIMARY KEY (match_id, position)
);
CREATE INDEX match_player_player_idx ON match_player (player_id);

CREATE TABLE screenshot (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    match_id uuid NOT NULL REFERENCES match(id) ON DELETE CASCADE,
    timecode_seconds integer NOT NULL,
    image bytea NOT NULL,
    image_format varchar(10) NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    created_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX screenshot_match_idx ON screenshot (match_id);

CREATE TABLE screenshot_like (
    screenshot_id uuid NOT NULL REFERENCES screenshot(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES app_user(id),
    created_at timestamp NOT NULL DEFAULT now(),
    PRIMARY KEY (screenshot_id, user_id)
);
CREATE INDEX screenshot_like_user_idx ON screenshot_like (user_id);
CREATE INDEX screenshot_like_screenshot_idx ON screenshot_like (screenshot_id);
